// registerCommunityBuildInPlugins 注册社区内置插件(内容来自 base-yak-plugin/cpNNNN__*.yak)
func registerCommunityBuildInPlugins() {
	for _, meta := range communityBuildInPluginMetas {
		codeBytes, err := basePluginFS.ReadFile("base-yak-plugin/" + meta.FileName)
		if err != nil || len(codeBytes) == 0 {
			log.Errorf("read community buildin plugin [%v] %v failed: %v", meta.ScriptName, meta.FileName, err)
			continue
		}
		opts := []pluginOption{}
		if meta.Help != "" {
			opts = append(opts, withPluginHelp(meta.Help))
		}
		if len(meta.Tags) > 0 {
			opts = append(opts, withPluginTags(meta.Tags))
		}
		if len(meta.OnlineContributors) > 0 {
			opts = append(opts, withPluginAuthors(meta.OnlineContributors...))
		}
		registerBuildInPluginContent(meta.PluginType, meta.ScriptName, string(codeBytes), opts...)
	}
}
